import React from 'react';

import styled from 'styled-components';

import { Icon } from '@openfin/ui-library';

import IconButton, { IconButtonProps } from '../IconButton/IconButton';

const CloseButtonLarge = (props: Omit<IconButtonProps, 'children'>) => {
    return (
        <CloseButtonContainer {...props}>
            <Icon icon="Cross2Icon" size="base" />
        </CloseButtonContainer>
    );
};

export default CloseButtonLarge;

const CloseButtonContainer = styled(IconButton)`
    svg path {
        opacity: 0.7;
    }

    &:hover:not(:disabled) {
        svg path {
            opacity: 1;
        }
    }
`;
