import { useCallback, useRef } from 'react';

import { SidePanelComponent, useSidePanelContext } from '@enterprise/context/SidePanelContext';

export const useBookmarksPanelFocus = () => {
    const panelRef = useRef<HTMLDivElement>(null);

    const { isSidePanelOpen, activeComponent, bookmarksButtonRef } = useSidePanelContext();

    const isBookmarksPanelOpen = isSidePanelOpen && activeComponent === SidePanelComponent.Bookmarks;

    const focusButton = useCallback(() => {
        if (bookmarksButtonRef.current) {
            bookmarksButtonRef.current.focus();
        }
    }, [bookmarksButtonRef]);

    const focusPanel = useCallback(() => {
        if (panelRef.current) {
            panelRef.current.focus();
        }
    }, []);

    return {
        panelRef,
        isBookmarksPanelOpen,
        focusButton,
        focusPanel
    };
};
